INSERT INTO ai_insights VALUES(1,'kelas',1,NULL,NULL,'mingguan','2026-W37','2026-09-07','2026-09-13','Materi "Fungsi Kuadrat" membutuhkan penguatan','Pada periode ini terdapat 50 jurnal dari 8 siswa. Sebagian besar siswa (68%) menunjukkan pemahaman yang cukup baik, namun 22% jurnal masih menyatakan belum paham. Materi yang paling sering dicatat sebagai tantangan: "Fungsi Kuadrat", "Usaha & Energi", "Trigonometri Dasar". Pola kesulitan yang menonjol adalah praktik & penerapan dan kerja sama & komunikasi. Suasana belajar paling sering terasa "biasa saja" (30% jurnal). Tingkat pengisian jurnal 63% dari hari belajar yang tersedia. Dibanding periode sebelumnya, proporsi pemahaman meningkat 68 poin persen (0% → 68%).','["50 jurnal dianalisis dari 8 siswa (dari 10 siswa terdaftar).","Distribusi pemahaman: Sangat paham 9 (18%), Paham 25 (50%), Cukup paham 5 (10%), Belum paham 11 (22%).","Materi tersulit: \"Fungsi Kuadrat\" (4 dari 4 jurnal, 88%); \"Usaha & Energi\" (2 dari 2 jurnal, 100%); \"Trigonometri Dasar\" (2 dari 3 jurnal, 67%).","Pola kesulitan: Praktik & penerapan (104 sebutan), Kerja sama & komunikasi (67 sebutan), Pemahaman instruksi (58 sebutan), Pemahaman konsep (54 sebutan).","Suasana belajar: Antusias 13, Senang 13, Biasa saja 15, Lelah 6, Bingung 3.","Rerata skor pemahaman 0 → 2.6 (skala 1–4), rerata keyakinan 0 → 3.3 (skala 1–5).","Tingkat pengisian jurnal 63% dari hari belajar dalam periode ini."]','[{"label":"Praktik & penerapan","kode":"praktik","jumlah":104,"keterangan":"Kata yang sering muncul: latihan, soal, mengerjakan"},{"label":"Kerja sama & komunikasi","kode":"kolaborasi","jumlah":67,"keterangan":"Kata yang sering muncul: diskusi, bertanya, teman"},{"label":"Pemahaman instruksi","kode":"instruksi","jumlah":58,"keterangan":"Kata yang sering muncul: soal, instruksi, langkah, teks"},{"label":"Pemahaman konsep","kode":"konsep","jumlah":54,"keterangan":"Kata yang sering muncul: penjelasan, hukum, konsep"},{"label":"Manajemen waktu & beban belajar","kode":"waktu","jumlah":4,"keterangan":"Kata yang sering muncul: waktu"}]','[{"kategori":"remedial","judul":"Penguatan materi \"Fungsi Kuadrat\"","isi":"Materi ini dicatat sebagai tantangan pada 4 dari 4 jurnal (88%) di X-1. Pertimbangkan sesi remedial singkat, lalu latihan terbimbing sebelum tugas mandiri."},{"kategori":"remedial","judul":"Penguatan materi \"Usaha & Energi\"","isi":"Materi ini dicatat sebagai tantangan pada 2 dari 2 jurnal (100%) di X-1. Pertimbangkan sesi remedial singkat, lalu latihan terbimbing sebelum tugas mandiri."},{"kategori":"remedial","judul":"Penguatan materi \"Trigonometri Dasar\"","isi":"Materi ini dicatat sebagai tantangan pada 2 dari 3 jurnal (67%) di X-1. Pertimbangkan sesi remedial singkat, lalu latihan terbimbing sebelum tugas mandiri."},{"kategori":"latihan_bertahap","judul":"Latihan bertahap dan terstruktur","isi":"Pola kesulitan menunjukkan hambatan saat menerapkan materi. Sediakan paket latihan bertingkat (mudah → sedang → menantang) dengan contoh pengerjaan pertama bersama-sama. Terdeteksi 104 sebutan terkait."},{"kategori":"diskusi_kelompok","judul":"Diskusi kelompok terarah","isi":"Siswa menyebut kerja sama dan keberanian bertanya sebagai kendala. Coba diskusi berpasangan dengan pertanyaan pemandu, lalu minta hasil diskusi disampaikan bergantian. Terdeteksi 67 sebutan terkait."},{"kategori":"contoh_kontekstual","judul":"Perjelas instruksi dengan contoh","isi":"Siswa melaporkan kebingungan memahami instruksi/soal. Perlihatkan satu contoh soal beserta cara membacanya, dan tandai kata kunci perintah sebelum pengerjaan mandiri. Terdeteksi 58 sebutan terkait."}]',81,'Analisis bersumber dari 50 jurnal siswa yang diisi secara sukarela pada periode ini, dari 10 siswa terdaftar. Siswa yang mengisi jurnal pada periode ini sekitar 80% — siswa yang belum mengisi tidak ikut terwakili. Pola kesulitan dihitung dari kata kunci pada tulisan refleksi siswa, sehingga sebagian istilah dapat tergolong ke lebih dari satu kategori. Periode analisis: mingguan, data lebih sedikit dari 10 jurnal sebaiknya dibaca sebagai indikasi awal saja. Sistem tidak melakukan penilaian, diagnosis psikologis, maupun keputusan otomatis terhadap siswa. Insight merupakan bantuan analisis dan perlu diverifikasi guru.','Mesin Analisis Lokal','2026-09-12 23:20:41','2026-09-12 23:20:41');
INSERT INTO ai_insights VALUES(2,'kelas',2,NULL,NULL,'mingguan','2026-W37','2026-09-07','2026-09-13','Materi "Gerak Lurus" membutuhkan penguatan','Pada periode ini terdapat 53 jurnal dari 9 siswa. Sebagian besar siswa (64%) menunjukkan pemahaman yang cukup baik, namun 11% jurnal masih menyatakan belum paham. Materi yang paling sering dicatat sebagai tantangan: "Gerak Lurus", "Kolonialisme", "Teks Berita". Pola kesulitan yang menonjol adalah praktik & penerapan dan kerja sama & komunikasi. Suasana belajar paling sering terasa "antusias" (32% jurnal). Tingkat pengisian jurnal 67% dari hari belajar yang tersedia. Dibanding periode sebelumnya, proporsi pemahaman meningkat 64 poin persen (0% → 64%).','["53 jurnal dianalisis dari 9 siswa (dari 10 siswa terdaftar).","Distribusi pemahaman: Sangat paham 11 (21%), Paham 23 (43%), Cukup paham 13 (25%), Belum paham 6 (11%).","Materi tersulit: \"Gerak Lurus\" (3 dari 5 jurnal, 50%); \"Kolonialisme\" (2 dari 2 jurnal, 75%); \"Teks Berita\" (2 dari 2 jurnal, 75%).","Pola kesulitan: Praktik & penerapan (111 sebutan), Kerja sama & komunikasi (72 sebutan), Pemahaman instruksi (62 sebutan), Pemahaman konsep (57 sebutan).","Suasana belajar: Antusias 17, Senang 12, Biasa saja 13, Lelah 9, Bingung 2.","Rerata skor pemahaman 0 → 2.7 (skala 1–4), rerata keyakinan 0 → 3.4 (skala 1–5).","Tingkat pengisian jurnal 67% dari hari belajar dalam periode ini."]','[{"label":"Praktik & penerapan","kode":"praktik","jumlah":111,"keterangan":"Kata yang sering muncul: latihan, soal, mengerjakan"},{"label":"Kerja sama & komunikasi","kode":"kolaborasi","jumlah":72,"keterangan":"Kata yang sering muncul: diskusi, teman, bertanya"},{"label":"Pemahaman instruksi","kode":"instruksi","jumlah":62,"keterangan":"Kata yang sering muncul: soal, teks, instruksi, langkah"},{"label":"Pemahaman konsep","kode":"konsep","jumlah":57,"keterangan":"Kata yang sering muncul: penjelasan, hukum, konsep"},{"label":"Manajemen waktu & beban belajar","kode":"waktu","jumlah":5,"keterangan":"Kata yang sering muncul: waktu"}]','[{"kategori":"penguatan_konsep","judul":"Penguatan materi \"Gerak Lurus\"","isi":"Materi ini dicatat sebagai tantangan pada 3 dari 5 jurnal (50%) di X-2. Pertimbangkan penguatan konsep dengan contoh kontekstual dan latihan bertahap, bukan penambahan materi baru."},{"kategori":"remedial","judul":"Penguatan materi \"Kolonialisme\"","isi":"Materi ini dicatat sebagai tantangan pada 2 dari 2 jurnal (75%) di X-2. Pertimbangkan sesi remedial singkat, lalu latihan terbimbing sebelum tugas mandiri."},{"kategori":"remedial","judul":"Penguatan materi \"Teks Berita\"","isi":"Materi ini dicatat sebagai tantangan pada 2 dari 2 jurnal (75%) di X-2. Pertimbangkan sesi remedial singkat, lalu latihan terbimbing sebelum tugas mandiri."},{"kategori":"latihan_bertahap","judul":"Latihan bertahap dan terstruktur","isi":"Pola kesulitan menunjukkan hambatan saat menerapkan materi. Sediakan paket latihan bertingkat (mudah → sedang → menantang) dengan contoh pengerjaan pertama bersama-sama. Terdeteksi 111 sebutan terkait."},{"kategori":"diskusi_kelompok","judul":"Diskusi kelompok terarah","isi":"Siswa menyebut kerja sama dan keberanian bertanya sebagai kendala. Coba diskusi berpasangan dengan pertanyaan pemandu, lalu minta hasil diskusi disampaikan bergantian. Terdeteksi 72 sebutan terkait."},{"kategori":"contoh_kontekstual","judul":"Perjelas instruksi dengan contoh","isi":"Siswa melaporkan kebingungan memahami instruksi/soal. Perlihatkan satu contoh soal beserta cara membacanya, dan tandai kata kunci perintah sebelum pengerjaan mandiri. Terdeteksi 62 sebutan terkait."}]',81,'Analisis bersumber dari 53 jurnal siswa yang diisi secara sukarela pada periode ini, dari 10 siswa terdaftar. Siswa yang mengisi jurnal pada periode ini sekitar 90% — siswa yang belum mengisi tidak ikut terwakili. Pola kesulitan dihitung dari kata kunci pada tulisan refleksi siswa, sehingga sebagian istilah dapat tergolong ke lebih dari satu kategori. Periode analisis: mingguan, data lebih sedikit dari 10 jurnal sebaiknya dibaca sebagai indikasi awal saja. Sistem tidak melakukan penilaian, diagnosis psikologis, maupun keputusan otomatis terhadap siswa. Insight merupakan bantuan analisis dan perlu diverifikasi guru.','Mesin Analisis Lokal','2026-09-12 23:20:41','2026-09-12 23:20:41');
