PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE academic_years (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nama TEXT NOT NULL UNIQUE,
  aktif INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE semesters (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  academic_year_id INTEGER NOT NULL REFERENCES academic_years(id) ON DELETE CASCADE,
  nama TEXT NOT NULL,
  aktif INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  UNIQUE (academic_year_id, nama)
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL UNIQUE,
  nama TEXT NOT NULL,
  email TEXT,
  telepon TEXT,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('admin','guru','walikelas','siswa')),
  aktif INTEGER NOT NULL DEFAULT 1,
  harus_ganti_sandi INTEGER NOT NULL DEFAULT 0,
  last_login_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE classes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nama TEXT NOT NULL,
  tingkat TEXT,
  academic_year_id INTEGER NOT NULL REFERENCES academic_years(id),
  wali_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  UNIQUE (nama, academic_year_id)
);
CREATE TABLE subjects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nama TEXT NOT NULL UNIQUE,
  kode TEXT,
  aktif INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE teachers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  nip TEXT,
  subject_id INTEGER REFERENCES subjects(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE teacher_classes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
  subject_id INTEGER REFERENCES subjects(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  UNIQUE (user_id, class_id, subject_id)
);
CREATE TABLE students (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE SET NULL,
  nis TEXT UNIQUE,
  nisn TEXT,
  nama TEXT NOT NULL,
  class_id INTEGER REFERENCES classes(id) ON DELETE SET NULL,
  jenis_kelamin TEXT,
  aktif INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE daily_journals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  class_id INTEGER REFERENCES classes(id) ON DELETE SET NULL,
  subject_id INTEGER REFERENCES subjects(id) ON DELETE SET NULL,
  teacher_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  academic_year_id INTEGER REFERENCES academic_years(id) ON DELETE SET NULL,
  semester_id INTEGER REFERENCES semesters(id) ON DELETE SET NULL,
  tanggal TEXT NOT NULL,
  jam_mulai TEXT,
  jam_selesai TEXT,
  materi TEXT NOT NULL DEFAULT '',
  aktivitas TEXT NOT NULL DEFAULT '',
  pemahaman TEXT,
  suasana TEXT,
  keyakinan INTEGER,
  ringkasan TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','terkirim','divalidasi','revisi')),
  sumber TEXT NOT NULL DEFAULT 'web',
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE journal_reflections (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  journal_id INTEGER NOT NULL REFERENCES daily_journals(id) ON DELETE CASCADE,
  kode TEXT NOT NULL,
  pertanyaan TEXT,
  jawaban TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  UNIQUE (journal_id, kode)
);
CREATE TABLE journal_feedback (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  journal_id INTEGER NOT NULL REFERENCES daily_journals(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  tipe TEXT NOT NULL DEFAULT 'apresiasi',
  isi TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE journal_validations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  journal_id INTEGER NOT NULL REFERENCES daily_journals(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  status TEXT NOT NULL,
  catatan TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE ai_insights (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  scope TEXT NOT NULL DEFAULT 'kelas',
  class_id INTEGER REFERENCES classes(id) ON DELETE CASCADE,
  student_id INTEGER REFERENCES students(id) ON DELETE CASCADE,
  subject_id INTEGER REFERENCES subjects(id) ON DELETE SET NULL,
  periode TEXT NOT NULL DEFAULT 'mingguan',
  periode_key TEXT NOT NULL,
  mulai TEXT,
  selesai TEXT,
  judul TEXT NOT NULL,
  ringkasan TEXT,
  bukti TEXT,
  pola TEXT,
  rekomendasi TEXT,
  keyakinan INTEGER DEFAULT 0,
  keterbatasan TEXT,
  mesin TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  UNIQUE (scope, class_id, student_id, subject_id, periode, periode_key)
);
CREATE TABLE ai_recommendations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  insight_id INTEGER REFERENCES ai_insights(id) ON DELETE CASCADE,
  class_id INTEGER REFERENCES classes(id) ON DELETE SET NULL,
  kategori TEXT NOT NULL,
  judul TEXT NOT NULL,
  isi TEXT NOT NULL,
  status_guru TEXT NOT NULL DEFAULT 'baru',
  catatan_guru TEXT,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  judul TEXT NOT NULL,
  isi TEXT,
  tipe TEXT NOT NULL DEFAULT 'info',
  link TEXT,
  dibaca INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE activity_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  aksi TEXT NOT NULL,
  entitas TEXT,
  entitas_id INTEGER,
  detail TEXT,
  ip TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE login_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT,
  ip TEXT,
  sukses INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE qr_codes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
  subject_id INTEGER REFERENCES subjects(id) ON DELETE SET NULL,
  token TEXT NOT NULL UNIQUE,
  dibuat_oleh INTEGER REFERENCES users(id) ON DELETE SET NULL,
  kedaluwarsa TEXT,
  aktif INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_jurnal_tanggal ON daily_journals (tanggal);
CREATE INDEX idx_jurnal_student_tanggal ON daily_journals (student_id, tanggal);
CREATE INDEX idx_jurnal_class_tanggal ON daily_journals (class_id, tanggal);
CREATE INDEX idx_jurnal_subject ON daily_journals (subject_id);
CREATE INDEX idx_jurnal_status ON daily_journals (status);
CREATE INDEX idx_refleksi_journal ON journal_reflections (journal_id);
CREATE INDEX idx_refleksi_kode ON journal_reflections (kode);
CREATE INDEX idx_feedback_journal ON journal_feedback (journal_id);
CREATE INDEX idx_validasi_journal ON journal_validations (journal_id);
CREATE INDEX idx_insight_scope ON ai_insights (scope, periode, periode_key);
CREATE INDEX idx_insight_class ON ai_insights (class_id, periode_key);
CREATE INDEX idx_rekomendasi_insight ON ai_recommendations (insight_id);
CREATE INDEX idx_rekomendasi_status ON ai_recommendations (status_guru);
CREATE INDEX idx_notif_user ON notifications (user_id, dibaca);
CREATE INDEX idx_log_created ON activity_logs (created_at);
CREATE INDEX idx_log_user ON activity_logs (user_id);
CREATE INDEX idx_attempt_username ON login_attempts (username, created_at);
CREATE INDEX idx_student_class ON students (class_id);
CREATE INDEX idx_teacher_classes_user ON teacher_classes (user_id, class_id);
COMMIT;
